from typing import Annotated
from fastapi import Depends, FastAPI, HTTPException
from sqlmodel import Field, Session, SQLModel, create_engine
from sqlmodel.pool import StaticPool

class Hero(SQLModel, table=True):
    id: int | None = Field(default=None, primary_key=True)
    name: str
    age: int | None = None

class HeroUpdate(SQLModel):
    name: str | None = None
    age: int | None = None

engine = create_engine("sqlite://", connect_args={"check_same_thread": False}, poolclass=StaticPool)
SQLModel.metadata.create_all(engine)
with Session(engine) as seed:
    seed.add(Hero(name="Ada", age=36))
    seed.commit()

def get_session():
    with Session(engine) as session:
        yield session

SessionDep = Annotated[Session, Depends(get_session)]
app = FastAPI()

def find_hero(hero_id: int, session: Session) -> Hero:
    hero = session.get(Hero, hero_id)
    if hero is None:
        raise HTTPException(status_code=404, detail="Hero not found")
    return hero

@app.get("/heroes/{hero_id}")
def read_hero(hero_id: int, session: SessionDep) -> Hero:
    return find_hero(hero_id, session)

@app.patch("/heroes/{hero_id}")
def update_hero(hero_id: int, patch: HeroUpdate, session: SessionDep) -> Hero:
    hero = find_hero(hero_id, session)
    hero.sqlmodel_update(patch.model_dump(exclude_unset=True))
    session.add(hero)
    session.commit()
    session.refresh(hero)
    return hero

@app.delete("/heroes/{hero_id}")
def delete_hero(hero_id: int, session: SessionDep) -> dict[str, bool]:
    hero = find_hero(hero_id, session)
    session.delete(hero)
    session.commit()
    return {"ok": True}
